function Login() {
  const [, setLocation] = useLocation(); const login = useLogin(); const [email, setEmail] = useState('agent@demo.com'); const [password, setPassword] = useState('Agent@123'); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); login.mutate({ data: { email, password } }, { onSuccess: (res: any) => { localStorage.setItem('resolveai_token', res.token); queryClient.setQueryData(getGetMeQueryKey(), res.user); setLocation(res.user.role === 'agent' ? '/agent/dashboard' : '/customer/cases'); }, onError: () => setError('We could not sign you in. Check your details and try again.') }); };
  return <AuthLayout eyebrow="Welcome back" title="Back to the work." subtitle="Sign in to pick up the conversation where you left it."><form onSubmit={submit} className="space-y-5"><Field label="Work email"><input data-testid="input-email" type="email" value={email} onChange={e => setEmail(e.target.value)} required placeholder="you@company.com" /></Field><Field label="Password"><input data-testid="input-password" type="password" value={password} onChange={e => setPassword(e.target.value)} required /></Field>{error && <ErrorMessage text={error} />}{login.isPending ? <Button className="w-full" disabled><RefreshCw size={16} className="animate-spin" /> Signing in</Button> : <Button className="w-full" type="submit" data-testid="button-sign-in"><LogIn size={16} /> Sign in</Button>}<div className="rounded-xl border border-secondary bg-secondary/50 p-4 text-xs leading-5 text-secondary-foreground"><b>Demo access</b><br />Agent: agent@demo.com · Agent@123<br />Customer: customer1@demo.com · Customer@123</div></form><p className="mt-7 text-center text-sm text-muted-foreground">New to ResolveAI? <Link href="/register" className="font-bold text-primary hover:underline" data-testid="link-create-account">Create an account</Link></p></AuthLayout>;
}
function Register() {
  const [, setLocation] = useLocation(); const register = useRegister(); const [form, setForm] = useState({ name: '', email: '', password: '' }); const [error, setError] = useState('');
  const update = (key: string) => (e: React.ChangeEvent<HTMLInputElement>) => setForm(v => ({ ...v, [key]: e.target.value }));
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); register.mutate({ data: form }, { onSuccess: (res: any) => { localStorage.setItem('resolveai_token', res.token); queryClient.setQueryData(getGetMeQueryKey(), res.user); setLocation('/customer/cases'); }, onError: () => setError('We could not create that account. Try another email.') }); };
  return <AuthLayout eyebrow="Get started" title="A clearer way to get help." subtitle="Create a customer account to report an issue, share evidence, and follow every step to resolution."><form onSubmit={submit} className="space-y-5"><Field label="Your name"><input data-testid="input-name" value={form.name} onChange={update('name')} required minLength={2} placeholder="Mina Patel" /></Field><Field label="Email"><input data-testid="input-register-email" type="email" value={form.email} onChange={update('email')} required placeholder="you@email.com" /></Field><Field label="Password"><input data-testid="input-register-password" type="password" value={form.password} onChange={update('password')} required minLength={8} placeholder="At least 8 characters" /></Field>{error && <ErrorMessage text={error} />}{register.isPending ? <Button className="w-full" disabled><RefreshCw size={16} className="animate-spin" /> Creating account</Button> : <Button className="w-full" type="submit" data-testid="button-create-account">Create customer account <ArrowRight size={16} /></Button>}</form><p className="mt-7 text-center text-sm text-muted-foreground">Already have an account? <Link href="/login" className="font-bold text-primary hover:underline" data-testid="link-sign-in">Sign in</Link></p></AuthLayout>;
}
function Field({ label, children }: { label: string; children: React.ReactNode }) { return <label className="block text-sm font-semibold">{label}<div className="mt-2 [&>input]:w-full [&>input]:rounded-lg [&>input]:border [&>input]:border-input [&>input]:bg-card [&>input]:px-3.5 [&>input]:py-3 [&>input]:text-sm [&>input]:font-normal [&>input]:outline-none [&>input]:focus:border-primary [&>input]:focus:ring-2 [&>input]:focus:ring-primary/15">{children}</div></label>; }
function ErrorMessage({ text }: { text: string }) { return <div className="flex items-start gap-2 rounded-lg border border-red-200 bg-red-50 p-3 text-sm text-red-700"><CircleAlert size={17} className="mt-0.5 shrink-0" />{text}</div>; }

function AppShell({ children, role }: { children: React.ReactNode; role: 'customer' | 'agent' }) {
  const [location, setLocation] = useLocation(); const [mobile, setMobile] = useState(false);
  const agent = role === 'agent'; const nav = agent ? [{ href: '/agent/dashboard', label: 'Overview', icon: LayoutDashboard }, { href: '/agent/cases', label: 'Case queue', icon: Inbox }] : [{ href: '/customer/cases', label: 'My cases', icon: Ticket }, { href: '/customer/report', label: 'Report an issue', icon: Plus }];
  return <div className="app-shell flex"><aside className={cx('fixed inset-y-0 left-0 z-40 w-[250px] bg-sidebar px-4 py-5 text-sidebar-foreground transition-transform lg:static lg:translate-x-0', mobile ? 'translate-x-0' : '-translate-x-full')}><div className="flex items-center justify-between px-3"><Logo light /><button className="text-sidebar-foreground/60 lg:hidden" onClick={() => setMobile(false)} data-testid="button-close-menu"><X size={18} /></button></div><div className="mt-10 px-3 text-[10px] font-bold uppercase tracking-[.18em] text-sidebar-foreground/45">{agent ? 'Agent console' : 'Customer portal'}</div><nav className="mt-3 space-y-1">{nav.map(item => { const I = item.icon; return <Link key={item.href} href={item.href} onClick={() => setMobile(false)} className={cx('flex items-center gap-3 rounded-lg px-3 py-3 text-sm font-semibold', location === item.href || location.startsWith(item.href + '/') ? 'bg-sidebar-primary text-sidebar-primary-foreground' : 'text-sidebar-foreground/70 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground')} data-testid={`link-nav-${item.label.toLowerCase().replaceAll(' ', '-')}`}><I size={17} />{item.label}</Link>; })}</nav><div className="mt-8 border-t border-sidebar-border pt-5"><div className="flex items-center gap-3 px-3 py-2 text-xs text-sidebar-foreground/60"><span className="grid size-8 place-items-center rounded-full bg-sidebar-accent text-xs font-bold text-sidebar-primary">{agent ? 'AM' : 'MP'}</span><div><div className="font-semibold text-sidebar-foreground">{agent ? 'Alex Morgan' : 'Priya Shah'}</div><div>{agent ? 'Resolution agent' : 'Customer'}</div></div></div><button className="mt-3 flex w-full items-center gap-3 rounded-lg px-3 py-2.5 text-sm text-sidebar-foreground/60 hover:bg-sidebar-accent hover:text-sidebar-accent-foreground" onClick={() => { localStorage.removeItem('resolveai_token'); queryClient.clear(); setLocation('/'); }} data-testid="button-sign-out"><LogIn size={16} className="rotate-180" /> Sign out</button></div><div className="absolute bottom-6 left-7 right-7 rounded-xl border border-sidebar-border bg-sidebar-accent/50 p-3 text-xs text-sidebar-foreground/65"><div className="flex items-center gap-2 font-semibold text-sidebar-foreground"><LifeBuoy size={14} className="text-sidebar-primary" /> Support cockpit</div><p className="mt-1 leading-5">Decision trail is active on every case.</p></div></aside><main className="min-w-0 flex-1"><div className="sticky top-0 z-30 flex h-[68px] items-center justify-between border-b border-border bg-background/90 px-5 backdrop-blur lg:px-9"><button className="rounded-lg p-2 hover:bg-muted lg:hidden" onClick={() => setMobile(true)} data-testid="button-open-menu"><Menu size={20} /></button><div className="hidden text-sm font-semibold text-muted-foreground lg:block">{agent ? 'ResolveAI / Agent console' : 'ResolveAI / Customer portal'}</div><div className="ml-auto flex items-center gap-2"><button className="rounded-lg p-2.5 text-muted-foreground hover:bg-muted" data-testid="button-notifications"><Bell size={18} /></button><button className="grid size-9 place-items-center rounded-full bg-secondary text-xs font-bold text-primary" data-testid="button-account">MP</button></div></div><div className="mx-auto max-w-[1400px] px-5 py-7 lg:px-9 lg:py-9">{children}</div></main></div>;
}

function CustomerCases() {
  const { data, isLoading, isError, refetch } = useGetMyCases(); const cases: any[] = data || [];
  return <AppShell role="customer"><PageHeader eyebrow="Customer portal" title="Your cases" body="A clear view of every conversation, from first report to resolution." action={<Link href="/customer/report" className="inline-flex items-center gap-2 rounded-lg bg-primary px-4 py-2.5 text-sm font-bold text-primary-foreground" data-testid="link-report-issue"><Plus size={17} /> Report an issue</Link>} /><div className="mb-7 grid gap-3 sm:grid-cols-3"><Stat label="Open cases" value={String(cases.filter(c => c.status !== 'Resolved').length || 0)} /><Stat label="Resolved" value={String(cases.filter(c => c.status === 'Resolved').length || 0)} /><Stat label="Last response" value="Today" /></div>{isLoading ? <LoadingBlock /> : isError ? <ErrorPanel retry={refetch} /> : cases.length === 0 ? <EmptyState title="No cases yet" body="When something goes sideways with an order, start here and we will help make it right." action={<Link href="/customer/report" className="font-bold text-primary" data-testid="link-empty-report">Report your first issue <ArrowRight size={14} className="inline" /></Link>} /> : <div className="space-y-3">{cases.map(c => <CaseListCard key={c.id} c={c} href={`/customer/cases/${c.id}`} />)}</div>}</AppShell>;
}
function CustomerReport() {
  const { data } = useGetMyOrders(); const orders: any[] = data || sampleOrders; const [orderId, setOrderId] = useState(''); const [message, setMessage] = useState(''); const [file, setFile] = useState<File | null>(null); const create = useCreateCase(); const upload = useUploadAttachment(); const [, setLocation] = useLocation(); const [error, setError] = useState('');
  const submit = (e: React.FormEvent) => { e.preventDefault(); setError(''); create.mutate({ data: { order_id: orderId ? Number(orderId) : null, message } }, { onSuccess: (res: any) => { if (file && res?.id) { const reader = new FileReader(); reader.onload = () => upload.mutate({ id: res.id, data: { file_name: file.name, file_data: String(reader.result).split(',')[1] || '' } }); reader.readAsDataURL(file); } queryClient.invalidateQueries({ queryKey: getGetMyCasesQueryKey() }); setLocation(`/customer/cases/${res.id}`); }, onError: () => setError('Your report could not be submitted. Please try again.') }); };
  return <AppShell role="customer"><Link href="/customer/cases" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-back-cases"><ArrowLeft size={16} /> Back to cases</Link><PageHeader eyebrow="New case" title="Tell us what happened." body="The more context you share, the faster we can find the right resolution." /><form onSubmit={submit} className="grid gap-6 lg:grid-cols-[1fr_340px]"><div className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-7"><label className="block text-sm font-bold">Which order is this about?<select value={orderId} onChange={e => setOrderId(e.target.value)} className="mt-2 w-full rounded-lg border border-input bg-card px-3.5 py-3 text-sm outline-none focus:border-primary" data-testid="select-order"><option value="">I am not sure / another order</option>{orders.map(o => <option key={o.id} value={o.id}>{o.order_code} · {o.product_name} · ${o.price}</option>)}</select></label><label className="mt-6 block text-sm font-bold">What can we help with?<textarea required minLength={10} value={message} onChange={e => setMessage(e.target.value)} rows={8} placeholder="Tell us what went wrong, what you expected, and how we can make this right." className="mt-2 w-full resize-none rounded-lg border border-input bg-card px-3.5 py-3 text-sm font-normal leading-6 outline-none focus:border-primary focus:ring-2 focus:ring-primary/15" data-testid="textarea-report-message" /></label><label className="mt-6 block cursor-pointer rounded-xl border border-dashed border-primary/40 bg-secondary/40 p-5 text-center hover:bg-secondary"><input type="file" className="sr-only" onChange={e => setFile(e.target.files?.[0] || null)} data-testid="input-evidence" /><Paperclip size={19} className="mx-auto text-primary" /><div className="mt-2 text-sm font-bold">{file ? file.name : 'Add evidence'}</div><div className="mt-1 text-xs text-muted-foreground">Photos, screenshots, or documents · optional</div></label>{error && <div className="mt-5"><ErrorMessage text={error} /></div>}<div className="mt-7 flex justify-end"><Button type="submit" disabled={create.isPending} data-testid="button-submit-report">{create.isPending ? 'Submitting…' : 'Submit report'} <ArrowRight size={16} /></Button></div></div><aside className="h-fit rounded-2xl border border-secondary bg-secondary/50 p-5"><div className="flex items-center gap-2 font-bold text-secondary-foreground"><ShieldCheck size={17} /> What happens next</div><ol className="mt-5 space-y-5 text-sm">{['We create a case and confirm receipt.', 'A support agent reviews the details and history.', 'You receive a clear next step in this case thread.'].map((x, i) => <li className="flex gap-3" key={x}><span className="grid size-6 shrink-0 place-items-center rounded-full bg-card text-xs font-bold text-primary shadow-sm">{i + 1}</span><span className="leading-5 text-secondary-foreground">{x}</span></li>)}</ol></aside></form></AppShell>;
}

function CaseListCard({ c, href }: { c: any; href: string }) { return <Link href={href} className="group block rounded-2xl border border-border bg-card p-5 shadow-sm hover:-translate-y-0.5 hover:border-primary/40 hover:shadow-md" data-testid={`card-case-${c.id}`}><div className="flex flex-wrap items-start justify-between gap-3"><div><div className="flex items-center gap-2"><span className="font-mono text-sm font-bold text-primary">{c.case_code || `RS-${c.id}`}</span><Badge tone={c.priority === 'Critical' || c.priority === 'High' ? 'red' : c.status === 'Resolved' ? 'teal' : 'neutral'}>{c.priority || c.status}</Badge></div><h3 className="mt-3 font-bold">{c.summary || 'Support case'}</h3><p className="mt-1 text-sm text-muted-foreground">{c.category || 'General support'} · Updated {relativeTime(c.updated_at || c.created_at)}</p></div><div className="flex items-center gap-2 text-sm font-semibold text-muted-foreground group-hover:text-primary">{c.status}<ArrowRight size={16} /></div></div><div className="mt-5 flex items-center justify-between border-t border-border pt-4 text-xs text-muted-foreground"><span className="flex items-center gap-1.5"><span className={cx('size-2 rounded-full', c.status === 'Resolved' ? 'bg-primary' : 'bg-amber-400')} /> {c.status}</span><span>{c.order?.order_code || 'Order details attached'}</span></div></Link>; }
function CustomerCaseDetail() { const params = useParams(); const id = Number(params.id); const { data, isLoading, isError, refetch } = useGetCase(id); return <AppShell role="customer"><Link href="/customer/cases" className="mb-6 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-back-customer-cases"><ArrowLeft size={16} /> All cases</Link>{isLoading ? <LoadingBlock rows={5} /> : isError || !data ? <ErrorPanel retry={refetch} /> : <CustomerCaseView c={data as any} />}</AppShell>; }
function CustomerCaseView({ c }: { c: any }) { const add = useAddCaseMessage(); const [body, setBody] = useState(''); const send = () => { if (!body.trim()) return; add.mutate({ id: c.id, data: { body } }, { onSuccess: () => { setBody(''); queryClient.invalidateQueries({ queryKey: getGetCaseQueryKey(c.id) }); } }); }; return <><PageHeader eyebrow={c.case_code} title={c.summary || 'Your support case'} body={`Opened ${formatDate(c.created_at)} · ${c.category || 'Support'}`} action={<Badge tone={c.status === 'Resolved' ? 'teal' : 'amber'}>{c.status}</Badge>} /><div className="grid gap-6 lg:grid-cols-[1fr_310px]"><div className="space-y-6"><Panel title="Conversation" icon={<MessageSquare size={17} />}>{(c.messages || []).length === 0 ? <p className="text-sm text-muted-foreground">Your report has been received. A team member will reply here.</p> : <div className="space-y-4">{c.messages.map((m: any) => <MessageBubble key={m.id} m={m} />)}</div>}<div className="mt-6 flex gap-2"><textarea value={body} onChange={e => setBody(e.target.value)} rows={2} placeholder="Add a message to your case…" className="min-w-0 flex-1 resize-none rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none focus:border-primary" data-testid="textarea-customer-message" /><Button onClick={send} disabled={add.isPending || !body.trim()} className="self-end px-3" data-testid="button-send-customer-message"><Send size={16} /></Button></div></Panel><Timeline events={c.timeline || []} /></div><aside className="space-y-4"><Panel title="Your next step" icon={<ArrowRight size={17} />}><p className="text-sm leading-6">{c.next_step || 'A support agent is reviewing your case.'}</p></Panel><Panel title="Evidence" icon={<FileImage size={17} />}>{(c.attachments || []).length ? c.attachments.map((a: any) => <div key={a.id} className="flex items-center gap-2 text-sm"><FileText size={15} className="text-primary" />{a.file_name}</div>) : <p className="text-sm text-muted-foreground">No files attached.</p>}</Panel></aside></div></>; }

function AgentDashboard() { const { data, isLoading, isError, refetch } = useGetAnalyticsSummary(); const a: any = data; return <AppShell role="agent"><PageHeader eyebrow="Monday, March 17" title="Good morning, Alex." body="Here is where the resolution queue stands today." action={<Button variant="secondary" onClick={() => refetch()} data-testid="button-refresh-analytics"><RefreshCw size={16} /> Refresh</Button>} />{isError ? <ErrorPanel retry={refetch} /> : isLoading ? <LoadingBlock rows={4} /> : <><div className="grid gap-3 sm:grid-cols-2 xl:grid-cols-5"><Stat label="Open cases" value={String(a?.open_cases ?? 42)} accent /><Stat label="High priority" value={String(a?.high_priority ?? 8)} tone="amber" /><Stat label="At risk" value={String(a?.at_risk ?? 3)} tone="red" /><Stat label="Resolved today" value={String(a?.resolved_today ?? 17)} tone="teal" /><Stat label="Repeat contact" value={`${a?.repeat_contact_rate ?? 12.4}%`} /></div><div className="mt-6 grid gap-6 lg:grid-cols-[1.3fr_.7fr]"><Panel title="Resolution pulse" icon={<Activity size={17} />} subtitle="Cases resolved per day"><MiniChart points={a?.per_day || [{ label: 'Mon', value: 15 }, { label: 'Tue', value: 21 }, { label: 'Wed', value: 18 }, { label: 'Thu', value: 27 }, { label: 'Fri', value: 22 }, { label: 'Sat', value: 29 }, { label: 'Sun', value: 24 }]} /></Panel><Panel title="Queue by status" icon={<Inbox size={17} />}><Bars points={a?.by_status || [{ label: 'New', value: 9 }, { label: 'Investigating', value: 17 }, { label: 'Awaiting customer', value: 8 }, { label: 'Approved', value: 5 }]} /></Panel></div><div className="mt-6"><Panel title="Needs attention" icon={<CircleAlert size={17} />} subtitle="Cases closest to their SLA"><div className="divide-y divide-border">{sampleCases.map(c => <Link href={`/agent/cases/${c.id}`} key={c.id} className="flex items-center justify-between gap-3 py-4 first:pt-1 hover:text-primary" data-testid={`link-attention-case-${c.id}`}><div className="flex items-center gap-3"><span className="grid size-9 place-items-center rounded-full bg-secondary text-xs font-bold text-primary">{c.customer_name.split(' ').map(x => x[0]).join('')}</span><div><div className="text-sm font-bold">{c.case_code} · {c.customer_name}</div><div className="mt-1 text-xs text-muted-foreground">{c.summary}</div></div></div><div className="hidden items-center gap-3 sm:flex"><Badge tone={c.priority === 'Critical' ? 'red' : 'amber'}>{c.priority}</Badge><span className="text-xs text-muted-foreground">{relativeTime(c.due_at)} due</span><ArrowRight size={15} /></div></Link>)}</div></Panel></div></>}</AppShell>; }
function AgentCases() { const [filters, setFilters] = useState({ status: '', priority: '', escalated: false }); const params: any = { ...(filters.status ? { status: filters.status } : {}), ...(filters.priority ? { priority: filters.priority } : {}), ...(filters.escalated ? { escalated: true } : {}) }; const { data, isLoading, isError, refetch } = useGetCases(params); const cases: any[] = data || sampleCases; return <AppShell role="agent"><PageHeader eyebrow="Operations" title="Case queue" body="Triage, assign, and move every case toward its next decision." action={<Button onClick={() => refetch()} variant="secondary" data-testid="button-refresh-cases"><RefreshCw size={16} /> Refresh queue</Button>} /><div className="mb-5 flex flex-wrap items-center gap-2 rounded-xl border border-border bg-card p-3 shadow-sm"><Filter size={16} className="ml-1 text-muted-foreground" /><select value={filters.status} onChange={e => setFilters(v => ({ ...v, status: e.target.value }))} className="rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none" data-testid="select-status-filter"><option value="">All statuses</option><option>New</option><option>Investigating</option><option>Awaiting Customer</option><option>Approved</option><option>Resolved</option></select><select value={filters.priority} onChange={e => setFilters(v => ({ ...v, priority: e.target.value }))} className="rounded-lg border border-input bg-background px-3 py-2 text-sm outline-none" data-testid="select-priority-filter"><option value="">All priorities</option><option>Critical</option><option>High</option><option>Medium</option><option>Low</option></select><button onClick={() => setFilters(v => ({ ...v, escalated: !v.escalated }))} className={cx('rounded-lg border px-3 py-2 text-sm font-semibold', filters.escalated ? 'border-primary bg-secondary text-primary' : 'border-input text-muted-foreground')} data-testid="button-escalated-filter"><CircleAlert size={15} className="inline mr-1.5" /> Escalated only</button><span className="ml-auto text-xs text-muted-foreground">{cases.length} cases</span></div>{isError ? <ErrorPanel retry={refetch} /> : isLoading ? <LoadingBlock rows={5} /> : <div className="overflow-hidden rounded-2xl border border-border bg-card shadow-sm"><div className="hidden grid-cols-[1fr_1.7fr_.65fr_.7fr_.8fr_28px] gap-4 border-b border-border bg-muted/50 px-5 py-3 text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground md:grid"><span>Case</span><span>Issue</span><span>Priority</span><span>Status</span><span>SLA</span><span /></div>{cases.map(c => <Link href={`/agent/cases/${c.id}`} key={c.id} className="grid items-center gap-3 border-b border-border px-5 py-4 last:border-b-0 hover:bg-secondary/30 md:grid-cols-[1fr_1.7fr_.65fr_.7fr_.8fr_28px] md:gap-4" data-testid={`row-agent-case-${c.id}`}><div className="flex items-center gap-3"><span className="grid size-8 place-items-center rounded-full bg-secondary text-[10px] font-bold text-primary">{initials(c.customer_name || 'Customer')}</span><div><div className="font-mono text-xs font-bold text-primary">{c.case_code}</div><div className="mt-1 text-xs font-semibold">{c.customer_name || 'Customer'}</div></div></div><div className="min-w-0"><div className="truncate text-sm font-semibold">{c.summary}</div><div className="mt-1 text-xs text-muted-foreground">{c.category}</div></div><div><Badge tone={c.priority === 'Critical' || c.priority === 'High' ? 'red' : c.priority === 'Medium' ? 'amber' : 'neutral'}>{c.priority}</Badge></div><div className="text-xs font-semibold text-muted-foreground">{c.status}</div><div className={cx('text-xs font-semibold', new Date(c.due_at) < new Date() ? 'text-destructive' : 'text-muted-foreground')}>{new Date(c.due_at) < new Date() ? 'Overdue' : relativeTime(c.due_at)}</div><ArrowRight size={16} className="hidden text-muted-foreground md:block" /></Link>)}</div>}</AppShell>; }

function AgentCaseDetail() { const id = Number(useParams().id); const { data, isLoading, isError, refetch } = useGetCase(id); return <AppShell role="agent">{isLoading ? <LoadingBlock rows={7} /> : isError || !data ? <ErrorPanel retry={refetch} /> : <AgentWorkspace c={data as any} />}</AppShell>; }
function AgentWorkspace({ c }: { c: any }) { const [, setLocation] = useLocation(); const qc = useQueryClient(); const [reply, setReply] = useState(''); const [override, setOverride] = useState(''); const [message, setMessage] = useState(''); const [tone, setTone] = useState('professional'); const generate = useGenerateReply(); const send = useSendReply(); const addMessage = useAddCaseMessage(); const updateStatus = useUpdateCaseStatus(); const overrideMutation = useOverrideCase(); const assign = useAssignCase(); const refresh = () => qc.invalidateQueries({ queryKey: getGetCaseQueryKey(c.id) }); const status = (s: string) => updateStatus.mutate({ id: c.id, data: { status: s as any } }, { onSuccess: refresh }); const generateReply = () => generate.mutate({ id: c.id, data: { body: c.summary || 'Please help with this case.', tone: tone as any } }, { onSuccess: (r: any) => setReply(r?.draft || '') }); const sendReply = () => { if (!reply.trim()) return; send.mutate({ id: c.id, data: { body: reply, tone: tone as any } }, { onSuccess: () => { setReply(''); refresh(); } }); }; const add = () => { if (!message.trim()) return; addMessage.mutate({ id: c.id, data: { body: message } }, { onSuccess: () => { setMessage(''); refresh(); } }); }; const saveOverride = () => { if (!override.trim()) return; overrideMutation.mutate({ id: c.id, data: { field: 'recommended_action', value: override } }, { onSuccess: () => { setOverride(''); refresh(); } }); }; return <><div className="mb-6 flex flex-wrap items-center justify-between gap-4"><div><Link href="/agent/cases" className="mb-3 inline-flex items-center gap-2 text-sm font-semibold text-muted-foreground hover:text-foreground" data-testid="link-back-agent-cases"><ArrowLeft size={16} /> Case queue</Link><div className="flex items-center gap-3"><span className="font-mono text-sm font-bold text-primary">{c.case_code}</span><Badge tone={c.priority === 'Critical' || c.priority === 'High' ? 'red' : 'amber'}>{c.priority}</Badge><Badge tone="neutral">{c.status}</Badge></div><h1 className="display mt-2 text-3xl font-bold">{c.summary || 'Customer case'}</h1><p className="mt-1 text-sm text-muted-foreground">{c.customer_name || 'Customer'} · {c.category} · Opened {formatDate(c.created_at)}</p></div><div className="flex gap-2"><select value={c.status} onChange={e => status(e.target.value)} className="rounded-lg border border-input bg-card px-3 py-2 text-sm font-semibold" data-testid="select-case-status"><option>New</option><option>Investigating</option><option>Awaiting Customer</option><option>Approved</option><option>Resolved</option><option>Rejected</option></select><Button variant="secondary" onClick={() => assign.mutate({ id: c.id, data: { agent_id: 1 } })} data-testid="button-assign-case"><Users size={16} /> Assign to me</Button></div></div><div className="grid gap-6 xl:grid-cols-[1fr_370px]"><div className="space-y-6"><Panel title="Customer conversation" icon={<MessageSquare size={17} />} subtitle="Visible to the customer"><div className="space-y-4">{(c.messages || []).length ? c.messages.map((m: any) => <MessageBubble key={m.id} m={m} />) : <p className="text-sm text-muted-foreground">No messages yet. Start with the customer report below.</p>}</div><div className="mt-5 border-t border-border pt-4"><textarea value={message} onChange={e => setMessage(e.target.value)} rows={3} placeholder="Add an internal or customer-facing message…" className="w-full resize-none rounded-lg border border-input bg-background p-3 text-sm outline-none focus:border-primary" data-testid="textarea-agent-message" /><div className="mt-2 flex justify-end"><Button onClick={add} disabled={addMessage.isPending || !message.trim()} data-testid="button-add-message"><Send size={15} /> Add message</Button></div></div></Panel><Timeline events={c.timeline || []} /></div><aside className="space-y-5"><Panel title="AI resolution brief" icon={<Bot size={17} />} subtitle="Review before you act"><div className="rounded-lg bg-secondary/60 p-4"><div className="text-[10px] font-bold uppercase tracking-[.14em] text-primary">Recommended action</div><p className="mt-2 text-sm font-semibold leading-6">{c.recommended_action || 'Review the customer history and choose the next best resolution.'}</p></div><div className="mt-4"><div className="text-[10px] font-bold uppercase tracking-[.14em] text-muted-foreground">Suggested next step</div><p className="mt-2 text-sm leading-5">{c.next_step || 'Confirm the missing information with the customer.'}</p></div>{c.missing_information?.length > 0 && <div className="mt-4 rounded-lg border border-accent bg-accent/40 p-3 text-xs leading-5 text-accent-foreground"><b>Missing information</b><ul className="mt-1 list-disc pl-4">{c.missing_information.map((x: string) => <li key={x}>{x}</li>)}</ul></div>}<div className="mt-5 border-t border-border pt-4"><div className="text-xs font-bold">Override recommendation</div><p className="mt-1 text-xs text-muted-foreground">Your decision will be attached to the case history.</p><textarea value={override} onChange={e => setOverride(e.target.value)} rows={2} placeholder="Why are you choosing a different action?" className="mt-3 w-full resize-none rounded-lg border border-input bg-background p-3 text-xs outline-none focus:border-primary" data-testid="textarea-ai-override" /><Button onClick={saveOverride} variant="secondary" className="mt-2 w-full" disabled={!override.trim() || overrideMutation.isPending} data-testid="button-override-ai"><ShieldCheck size={15} /> Record override</Button></div></Panel><Panel title="Draft a reply" icon={<Sparkles size={17} />} subtitle="AI-assisted, always editable"><div className="flex gap-2"><select value={tone} onChange={e => setTone(e.target.value)} className="min-w-0 flex-1 rounded-lg border border-input bg-background px-2 py-2 text-xs" data-testid="select-reply-tone"><option value="professional">Professional</option><option value="warm">Warm</option><option value="concise">Concise</option></select><Button variant="secondary" onClick={generateReply} disabled={generate.isPending} className="px-3" data-testid="button-generate-reply">{generate.isPending ? <RefreshCw size={15} className="animate-spin" /> : <Sparkles size={15} />} Generate</Button></div><textarea value={reply} onChange={e => setReply(e.target.value)} rows={6} placeholder="Generate a draft or write a reply from scratch…" className="mt-3 w-full resize-none rounded-lg border border-input bg-background p-3 text-sm leading-5 outline-none focus:border-primary" data-testid="textarea-reply-draft" /><Button onClick={sendReply} disabled={!reply.trim() || send.isPending} className="mt-2 w-full" data-testid="button-send-reply"><Send size={15} /> {send.isPending ? 'Sending…' : 'Send reply'}</Button></Panel></aside></div></>; }

function PageHeader({ eyebrow, title, body, action }: { eyebrow: string; title: string; body: string; action?: React.ReactNode }) { return <div className="mb-7 flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-bold uppercase tracking-[.17em] text-primary">{eyebrow}</p><h1 className="display mt-2 text-3xl font-bold sm:text-4xl">{title}</h1><p className="mt-2 text-sm text-muted-foreground">{body}</p></div>{action}</div>; }
function Stat({ label, value, accent, tone }: { label: string; value: string; accent?: boolean; tone?: 'amber' | 'red' | 'teal' }) { return <div className="rounded-xl border border-border bg-card p-4 shadow-sm"><div className="flex items-center justify-between"><span className="text-xs font-semibold text-muted-foreground">{label}</span><span className={cx('size-2 rounded-full', accent || tone === 'teal' ? 'bg-primary' : tone === 'amber' ? 'bg-amber-400' : tone === 'red' ? 'bg-destructive' : 'bg-muted-foreground/40')} /></div><div className="mt-3 text-2xl font-bold">{value}</div></div>; }
function Panel({ title, subtitle, icon, children }: { title: string; subtitle?: string; icon?: React.ReactNode; children: React.ReactNode }) { return <section className="rounded-2xl border border-border bg-card p-5 shadow-sm sm:p-6"><div className="mb-5 flex items-start gap-3">{icon && <span className="grid size-8 shrink-0 place-items-center rounded-lg bg-secondary text-primary">{icon}</span>}<div><h2 className="text-sm font-bold">{title}</h2>{subtitle && <p className="mt-1 text-xs text-muted-foreground">{subtitle}</p>}</div></div>{children}</section>; }
function Timeline({ events }: { events: any[] }) { return <Panel title="Decision timeline" icon={<Activity size={17} />} subtitle="A complete record of this case"><div className="space-y-5">{events.length ? events.map(e => <div key={e.id} className="relative flex gap-3"><span className="relative z-10 mt-0.5 grid size-7 shrink-0 place-items-center rounded-full border border-secondary bg-secondary text-primary"><Check size={14} /></span><div className="min-w-0"><div className="text-sm font-semibold">{e.description}</div><div className="mt-1 text-xs text-muted-foreground">{e.actor_type} · {formatDate(e.created_at)}</div></div></div>) : <p className="text-sm text-muted-foreground">Timeline events will appear as the case moves forward.</p>}</div></Panel>; }
function MessageBubble({ m }: { m: any }) { const customer = m.sender_type === 'customer'; return <div className={cx('flex gap-3', !customer && 'flex-row-reverse')}><span className={cx('grid size-8 shrink-0 place-items-center rounded-full text-[10px] font-bold', customer ? 'bg-secondary text-primary' : 'bg-sidebar text-sidebar-foreground')}>{customer ? 'CU' : 'AG'}</span><div className={cx('max-w-[82%] rounded-xl px-4 py-3 text-sm leading-6', customer ? 'bg-muted' : 'bg-secondary/65')}><p>{m.body}</p><div className="mt-1 text-[10px] text-muted-foreground">{formatDate(m.created_at)}</div></div></div>; }
function Bars({ points }: { points: any[] }) { const max = Math.max(...points.map(p => p.value), 1); return <div className="space-y-4">{points.map(p => <div key={p.label}><div className="mb-1.5 flex justify-between text-xs"><span className="text-muted-foreground">{p.label}</span><b>{p.value}</b></div><div className="h-2 rounded-full bg-muted"><div className="h-2 rounded-full bg-primary" style={{ width: `${(p.value / max) * 100}%` }} /></div></div>)}</div>; }
function MiniChart({ points }: { points: any[] }) { const max = Math.max(...points.map(p => p.value), 1); return <div className="flex h-44 items-end gap-2 border-b border-border pb-1 pt-6">{points.map(p => <div key={p.label} className="flex min-w-0 flex-1 flex-col items-center gap-2"><div className="w-full rounded-t-md bg-primary/80 hover:bg-primary" style={{ height: `${Math.max(12, (p.value / max) * 125)}px` }} title={`${p.label}: ${p.value}`} /><span className="text-[10px] text-muted-foreground">{p.label}</span></div>)}</div>; }
function ErrorPanel({ retry }: { retry: () => void }) { return <div className="rounded-2xl border border-red-200 bg-red-50 p-8 text-center"><CircleAlert className="mx-auto text-red-600" size={24} /><h3 className="mt-3 font-bold text-red-900">Something interrupted the queue</h3><p className="mt-1 text-sm text-red-700">We could not load this view. Your work is safe.</p><Button onClick={retry} variant="secondary" className="mt-5 border-red-200 bg-card text-red-700" data-testid="button-retry"><RefreshCw size={15} /> Try again</Button></div>; }
function initials(name: string) { return name.split(' ').map(x => x[0]).slice(0, 2).join('').toUpperCase(); }
function formatDate(value?: string) { if (!value) return '—'; return new Date(value).toLocaleDateString(undefined, { month: 'short', day: 'numeric', year: 'numeric' }); }
function relativeTime(value?: string) { if (!value) return 'recently'; const diff = new Date(value).getTime() - Date.now(); const mins = Math.round(Math.abs(diff) / 60000); if (mins < 60) return `${mins || 1}m`; const hrs = Math.round(mins / 60); if (hrs < 24) return `${hrs}h`; return `${Math.round(hrs / 24)}d`; }

function Router() { return <ErrorBoundary resetKey={location.pathname}><Switch><Route path="/" component={Landing} /><Route path="/login" component={Login} /><Route path="/register" component={Register} /><Route path="/customer/cases" component={CustomerCases} /><Route path="/customer/report" component={CustomerReport} /><Route path="/customer/cases/:id" component={CustomerCaseDetail} /><Route path="/agent/dashboard" component={AgentDashboard} /><Route path="/agent/cases" component={AgentCases} /><Route path="/agent/cases/:id" component={AgentCaseDetail} /><Route component={() => <div className="grid min-h-[100dvh] place-items-center bg-background"><div className="text-center"><div className="display text-6xl font-bold text-primary">404</div><p className="mt-3 text-muted-foreground">This route does not exist.</p><Link href="/" className="mt-5 inline-block font-bold text-primary" data-testid="link-not-found-home">Return home</Link></div></div>} /></Switch></ErrorBoundary>; }
function App() { return <QueryClientProvider client={queryClient}><TooltipProvider><Router /><Toaster /></TooltipProvider></QueryClientProvider>; }
export default App;